#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end;
    long n = strtol(argv[1], &end, 10);
    if (end == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    long k = strtol(argv[2], &end, 10);
    if (end == argv[2]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000L || k > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long result = 0;
    for (long i = 2; i <= n; ++i) {
        result = (result + k) % i;
    }
    printf("%ld\n", result + 1);
    return 0;
}
